function validate([arr, k]) {
  if (!Array.isArray(arr) || arr.length < 2 || arr.length > 1000) return 'arr needs 2 to 1000 values.';
  if (arr[0] !== 1) return 'arr must start with 1.';
  const isPrime = (v) => {
    if (v < 2) return false;
    for (let d = 2; d * d <= v; d++) if (v % d === 0) return false;
    return true;
  };
  for (let i = 1; i < arr.length; i++) {
    if (!Number.isInteger(arr[i]) || arr[i] > 30000) return 'Each value is a whole number up to 3 * 10^4.';
    if (arr[i] <= arr[i - 1]) return 'arr must be strictly increasing.';
    if (!isPrime(arr[i])) return 'Every value after the first must be a prime.';
  }
  const total = arr.length * (arr.length - 1) / 2;
  if (!Number.isInteger(k) || k < 1 || k > total) return 'k is between 1 and the number of fractions.';
  return null;
}

