function kthSmallestPrimeFraction(arr, k) {
  const fractions = [];
  for (let i = 0; i < arr.length; i++)
    for (let j = i + 1; j < arr.length; j++) fractions.push([arr[i], arr[j]]);
  fractions.sort((x, y) => x[0] * y[1] - y[0] * x[1]);
  return fractions[k - 1];
}

