function generate(rand, size) {
  const primes = [];
  const composite = new Uint8Array(30000);
  for (let v = 2; v < 30000; v++) {
    if (composite[v]) continue;
    primes.push(v);
    for (let m = v * v; m < 30000; m += v) composite[m] = 1;
  }
  // Large inputs either use all 1000 slots with a moderate k, or about 280 values with k near the very end,
  // so that a heap needing k pops stays within the local time limit.
  const wide = rand() < 0.6;
  const n = size === 'large' ? (wide ? 1000 : 250 + Math.floor(rand() * 31)) : 2 + Math.floor(rand() * 7);
  // Small inputs mostly draw from the first primes so that fractions sit close together.
  const pool = size === 'large' || rand() < 0.3 ? primes.length : 15;
  const chosen = new Set();
  while (chosen.size < n - 1) chosen.add(primes[Math.floor(rand() * pool)]);
  const arr = [1, ...[...chosen].sort((a, b) => a - b)];
  const total = n * (n - 1) / 2;
  const pick = rand();
  if (size === 'large') return [arr, wide ? 1 + Math.floor(pick * 40000) : total - Math.floor(pick * 200)];
  const k = pick < 0.15 ? 1 : pick < 0.3 ? total : 1 + Math.floor(rand() * total);
  return [arr, k];
}
